     1→/**
     2→ * Next.js Middleware for Authentication & Session Management
     3→ *
     4→ * Bu middleware aşağıdaki işlevleri gerçekleştirir:
     5→ * 1. Session refresh - Her istekte Supabase oturumunu yeniler
     6→ * 2. Protected routes - Kimliği doğrulanmamış kullanıcıları login'e yönlendirir
     7→ * 3. Admin koruması - Super admin olmayanları admin panelden uzak tutar
     8→ * 4. Public routes - Menü ve auth sayfalarına serbest erişim sağlar
     9→ *
    10→ * @see https://supabase.com/docs/guides/auth/server-side/nextjs
    11→ */
    12→
    13→import { createServerClient, type CookieOptions } from '@supabase/ssr';
    14→import { NextResponse, type NextRequest } from 'next/server';
    15→
    16→/**
    17→ * Public routes - kimlik doğrulama gerektirmeyen yollar
    18→ * Bu yollara herkes erişebilir
    19→ */
    20→const PUBLIC_ROUTES = [
    21→  '/', // Landing page
    22→  '/login',
    23→  '/register',
    24→  '/auth/callback',
    25→  '/menu', // Public menu pages (/menu/[slug])
    26→];
    27→
    28→/**
    29→ * Protected routes - kimlik doğrulama gerektiren yollar
    30→ * Giriş yapmamış kullanıcılar login'e yönlendirilir
    31→ */
    32→const PROTECTED_ROUTES = [
    33→  '/dashboard',
    34→  '/settings',
    35→  '/products',
    36→  '/categories',
    37→  '/tables',
    38→  '/waiter',
    39→  '/audit',
    40→];
    41→
    42→/**
    43→ * Admin routes - super admin yetkisi gerektiren yollar
    44→ * Sadece is_super_admin=true olan kullanıcılar erişebilir
    45→ */
    46→const ADMIN_ROUTES = ['/admin'];
    47→
    48→/**
    49→ * Supabase session'ını günceller ve gerekli cookie'leri ayarlar
    50→ * Bu fonksiyon her request'te çağrılmalıdır
    51→ */
    52→async function updateSession(request: NextRequest) {
    53→  // Response'u başlat - cookie'ler buraya yazılacak
    54→  let response = NextResponse.next({
    55→    request: {
    56→      headers: request.headers,
    57→    },
    58→  });
    59→
    60→  // Middleware için Supabase client oluştur
    61→  // NOT: Bu, server.ts'den farklıdır çünkü middleware'de
    62→  // cookie'leri NextResponse üzerinden yönetmemiz gerekir
    63→  const supabase = createServerClient(
    64→    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    65→    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    66→    {
    67→      cookies: {
    68→        getAll() {
    69→          return request.cookies.getAll();
    70→        },
    71→        setAll(cookiesToSet) {
    72→          // Request cookies'e de ekle (Server Components için)
    73→          cookiesToSet.forEach(({ name, value }) => {
    74→            request.cookies.set(name, value);
    75→          });
    76→
    77→          // Response'u yeniden oluştur ve cookie'leri ekle
    78→          response = NextResponse.next({
    79→            request: {
    80→              headers: request.headers,
    81→            },
    82→          });
    83→
    84→          cookiesToSet.forEach(({ name, value, options }) => {
    85→            response.cookies.set(name, value, options as CookieOptions);
    86→          });
    87→        },
    88→      },
    89→    }
    90→  );
    91→
    92→  // CRITICAL: getUser() kullanarak session'ı doğrula
    93→  // getSession() sunucu tarafında güvenli değildir çünkü
    94→  // JWT token doğrulaması yapmaz
    95→  const {
    96→    data: { user },
    97→    error,
    98→  } = await supabase.auth.getUser();
    99→
   100→  return { response, user, error, supabase };
   101→}
   102→
   103→/**
   104→ * Verilen pathname'in belirtilen route'lardan biriyle eşleşip eşleşmediğini kontrol eder
   105→ */
   106→function matchesRoutes(pathname: string, routes: string[]): boolean {
   107→  return routes.some((route) => {
   108→    // Exact match veya prefix match (alt sayfalar için)
   109→    return pathname === route || pathname.startsWith(`${route}/`);
   110→  });
   111→}
   112→
   113→/**
   114→ * Ana middleware fonksiyonu
   115→ */
   116→export async function middleware(request: NextRequest) {
   117→  const { pathname } = request.nextUrl;
   118→
   119→  // Static dosyaları ve API route'larını atla
   120→  // (config.matcher'da da belirtilmiş ama ekstra güvenlik için)
   121→  if (
   122→    pathname.startsWith('/_next') ||
   123→    pathname.startsWith('/api') ||
   124→    pathname.includes('.') // .css, .js, .png vb.
   125→  ) {
   126→    return NextResponse.next();
   127→  }
   128→
   129→  // Session'ı güncelle
   130→  const { response, user, supabase } = await updateSession(request);
   131→
   132→  // Public routes - herkes erişebilir
   133→  if (matchesRoutes(pathname, PUBLIC_ROUTES)) {
   134→    // Eğer kullanıcı giriş yapmışsa ve login/register'a gidiyorsa
   135→    // dashboard'a yönlendir
   136→    if (user && (pathname === '/login' || pathname === '/register')) {
   137→      const dashboardUrl = new URL('/dashboard', request.url);
   138→      return NextResponse.redirect(dashboardUrl);
   139→    }
   140→    return response;
   141→  }
   142→
   143→  // Admin routes - super admin kontrolü
   144→  if (matchesRoutes(pathname, ADMIN_ROUTES)) {
   145→    if (!user) {
   146→      // Kullanıcı giriş yapmamış - login'e yönlendir
   147→      const loginUrl = new URL('/login', request.url);
   148→      loginUrl.searchParams.set('redirectTo', pathname);
   149→      return NextResponse.redirect(loginUrl);
   150→    }
   151→
   152→    // Super admin kontrolü - users tablosundan is_super_admin kontrolü
   153→    const { data: userData } = await supabase
   154→      .from('users')
   155→      .select('is_super_admin')
   156→      .eq('id', user.id)
   157→      .single();
   158→
   159→    if (!userData?.is_super_admin) {
   160→      // Super admin değil - dashboard'a yönlendir
   161→      const dashboardUrl = new URL('/dashboard', request.url);
   162→      return NextResponse.redirect(dashboardUrl);
   163→    }
   164→
   165→    return response;
   166→  }
   167→
   168→  // Protected routes - giriş kontrolü
   169→  if (matchesRoutes(pathname, PROTECTED_ROUTES)) {
   170→    if (!user) {
   171→      // Kullanıcı giriş yapmamış - login'e yönlendir
   172→      // redirectTo parametresi ile giriş sonrası dönüş yolunu kaydet
   173→      const loginUrl = new URL('/login', request.url);
   174→      loginUrl.searchParams.set('redirectTo', pathname);
   175→      return NextResponse.redirect(loginUrl);
   176→    }
   177→
   178→    return response;
   179→  }
   180→
   181→  // Diğer tüm route'lar için session güncellemesiyle devam et
   182→  return response;
   183→}
   184→
   185→/**
   186→ * Middleware config
   187→ * Hangi route'larda middleware'in çalışacağını belirler
   188→ */
   189→export const config = {
   190→  matcher: [
   191→    /*
   192→     * Match all request paths except:
   193→     * - _next/static (static files)
   194→     * - _next/image (image optimization files)
   195→     * - favicon.ico (favicon file)
   196→     * - public files (images, fonts, etc.)
   197→     */
   198→    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|css|js|woff|woff2|ttf|eot)$).*)',
   199→  ],
   200→};
