     1→/**
     2→ * Server Supabase Client
     3→ *
     4→ * Bu dosya server-side (Server Components, Route Handlers, Server Actions)
     5→ * Supabase bağlantısı için kullanılır.
     6→ *
     7→ * NOT: Bu fonksiyon async'dir çünkü Next.js 15'te cookies() artık
     8→ * async bir fonksiyondur.
     9→ *
    10→ * @example
    11→ * ```tsx
    12→ * // Server Component veya Route Handler içinde
    13→ * import { createServerSupabaseClient } from '@/lib/supabase/server';
    14→ *
    15→ * export default async function Page() {
    16→ *   const supabase = await createServerSupabaseClient();
    17→ *   const { data } = await supabase.from('products').select();
    18→ *   // ...
    19→ * }
    20→ * ```
    21→ */
    22→
    23→import { createServerClient } from '@supabase/ssr';
    24→import { cookies } from 'next/headers';
    25→
    26→export async function createServerSupabaseClient() {
    27→  const cookieStore = await cookies();
    28→
    29→  return createServerClient(
    30→    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    31→    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    32→    {
    33→      cookies: {
    34→        getAll() {
    35→          return cookieStore.getAll();
    36→        },
    37→        setAll(cookiesToSet) {
    38→          try {
    39→            cookiesToSet.forEach(({ name, value, options }) =>
    40→              cookieStore.set(name, value, options)
    41→            );
    42→          } catch {
    43→            // Server Component'ta setAll çağrılabilir ama yazma başarısız olabilir.
    44→            // Bu durum Middleware veya Route Handler'da düzeltilir.
    45→          }
    46→        },
    47→      },
    48→    }
    49→  );
    50→}
