     1→/**
     2→ * Feature Permission Guard
     3→ *
     4→ * Dinamik paket kontrolü için kullanılır.
     5→ * ASLA hard-coded paket kontrolü yapılmaz (if package == 'Pro' YASAK).
     6→ *
     7→ * Kontrol sırası:
     8→ * 1. organization_feature_overrides tablosu kontrol edilir
     9→ * 2. Override yoksa, plan_features tablosu kontrol edilir
    10→ *
    11→ * @example
    12→ * ```ts
    13→ * // Server Component veya Route Handler içinde
    14→ * import { hasPermission, getFeatureLimit } from '@/lib/guards/permission';
    15→ *
    16→ * // Boolean özellik kontrolü
    17→ * if (await hasPermission(orgId, 'module_waiter_call')) {
    18→ *   // Garson çağırma özelliği aktif
    19→ * }
    20→ *
    21→ * // Limit kontrolü
    22→ * const maxProducts = await getFeatureLimit(orgId, 'limit_menu_items');
    23→ * if (maxProducts === -1 || currentCount < maxProducts) {
    24→ *   // Yeni ürün eklenebilir
    25→ * }
    26→ * ```
    27→ */
    28→
    29→import { createServerSupabaseClient } from '@/lib/supabase/server';
    30→import type { FeatureKey, FeatureCheckResult, UUID } from '@/types';
    31→
    32→// Type definitions for Supabase query results
    33→interface PlanFeatureResult {
    34→  feature: { key: string } | null;
    35→  value_boolean: boolean | null;
    36→  value_limit: number | null;
    37→}
    38→
    39→interface PlanWithFeatures {
    40→  plan_features: PlanFeatureResult[];
    41→}
    42→
    43→interface SubscriptionWithPlan {
    44→  expires_at: string | null;
    45→  status?: string;
    46→  plan: PlanWithFeatures;
    47→}
    48→
    49→/**
    50→ * Check if an organization has permission for a specific feature.
    51→ *
    52→ * This function follows the override-first pattern:
    53→ * 1. First checks organization_feature_overrides (custom grants/revokes)
    54→ * 2. If no override, checks plan_features from active subscription
    55→ *
    56→ * CRITICAL: NO hard-coded package checks (e.g., if (plan === 'Pro') is FORBIDDEN)
    57→ *
    58→ * @param organizationId - The organization UUID to check permission for
    59→ * @param featureKey - The feature key to check (e.g., 'module_waiter_call')
    60→ * @returns Promise<boolean> - true if permission granted, false otherwise
    61→ */
    62→export async function hasPermission(
    63→  organizationId: UUID,
    64→  featureKey: FeatureKey
    65→): Promise<boolean> {
    66→  const supabase = await createServerSupabaseClient();
    67→
    68→  // 1. Check organization_feature_overrides first (highest priority)
